using System.Text.Json;using CustomCodeFramework.Redis.Streams.Abstractions;using CustomCodeFramework.Redis.Streams.Messages;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Mongo;namespace Dhole.Content.Worker.Streams;
internal abstract class ContentProjectionStreamHandlerBase(IContentCacheService cache,IContentChangeSnapshotWriter snapshots,ILogger logger):IRedisStreamMessageHandler{public abstract string MessageType{get;}protected virtual bool InvalidateContent=>false;protected virtual bool InvalidateMenu=>false;protected virtual bool InvalidateSettings=>false;public async Task HandleAsync(RedisStreamEnvelope envelope,CancellationToken ct=default){var identity=Read(envelope.PayloadJson);var site=string.IsNullOrWhiteSpace(identity.SiteKey)?"main":identity.SiteKey;if(InvalidateContent&&!string.IsNullOrWhiteSpace(identity.Slug))await cache.RemoveContentAsync(site,identity.Slug,ct);if(InvalidateMenu&&!string.IsNullOrWhiteSpace(identity.Location))await cache.RemoveMenuAsync(site,identity.Location,ct);if(InvalidateSettings)await cache.RemovePublicSettingsAsync(site,ct);await snapshots.WriteAsync(envelope.MessageId,envelope.MessageType,identity.EntityId,site,identity.Slug,envelope.PayloadJson??"{}",null,DateTime.UtcNow,ct);logger.LogInformation("Content projection handled {MessageType}. MessageId={MessageId}, EntityId={EntityId}, SiteKey={SiteKey}.",envelope.MessageType,envelope.MessageId,identity.EntityId,site);}private static Identity Read(string? json){if(string.IsNullOrWhiteSpace(json))return new(null,null,null,null);using var doc=JsonDocument.Parse(json);var r=doc.RootElement;return new Identity(P(r,"id")??P(r,"Id"),P(r,"siteKey")??P(r,"SiteKey"),P(r,"slug")??P(r,"Slug"),P(r,"location")??P(r,"Location"));}private static string? P(JsonElement e,string n)=>e.TryGetProperty(n,out var p)?p.ToString():null;private sealed record Identity(string? EntityId,string? SiteKey,string? Slug,string? Location);}
